IDX = [["2026-10-18",11817.42,0.1,-4.6],["2026-10-19",11801.29,-0.1,-4.5],["2026-10-20",11704.35,-0.8,-3.4],["2026-10-21",11357.32,-3.0,-3.9],["2026-10-22",11673.83,2.8,-1.1],["2026-10-25",11534.38,-1.2,-2.4],["2026-10-26",11245.73,-2.5,-4.7],["2026-10-27",11470.03,2.0,-2.0]]


def session(label):            # 数据源时间戳是 T16:00Z，交易日 = 标签 + 1 天
    d = dt.date.fromisoformat(label) + dt.timedelta(days=1)
    return d


def score(row, idx_r5):
    _, _, _, vr, ma_up, r5 = row
    rs = r5 - idx_r5
    v, p, s = vr >= VOL_MULT, bool(ma_up), rs >= RS_GAP
    return int(v) + int(p) + int(s), rs


def build():
    idx_r5 = {r[0]: r[3] for r in IDX}
    labels = [r[0] for r in IDX]
    today = labels[-1]
    themes = []
    for t in THEMES:
        stocks, timeline = [], []
        for lb in labels:
            n = sum(1 for code, _ in t["stocks"]
                    if code in D and score(next(r for r in D[code] if r[0] == lb),
                                           idx_r5[lb])[0] == 3)
            timeline.append({"d": session(lb).strftime("%m/%d"), "n": n})
        for code, name in t["stocks"]:
            if code not in D:
                continue
            row = D[code][-1]
            sc, rs = score(row, idx_r5[today])
            stocks.append({"name": name, "code": code.split(".")[0],
                           "px": row[1], "chg": row[2], "vol": row[3],
                           "ma": bool(row[4]), "rs": round(rs, 1), "score": sc})
        stocks.sort(key=lambda s: (-s["score"], -s["rs"]))
        hits = sum(1 for s in stocks if s["score"] == 3)
        avg_chg = sum(s["chg"] for s in stocks) / len(stocks)
        avg_sc = sum(s["score"] for s in stocks) / len(stocks)
        themes.append({"id": t["id"], "name": t["name"], "fired": hits >= TRIGGER,
                       "hits": hits, "total": len(stocks),
                       "basketChg": round(avg_chg, 1), "avgScore": round(avg_sc, 2),
                       "stocks": stocks, "timeline": timeline})
    themes.sort(key=lambda t: (-int(t["fired"]), -t["hits"], -t["avgScore"], -t["basketChg"]))
    ix = IDX[-1]
    sd = session(today)
    return {
        "date": sd.isoformat(),
        "updated": sd.isoformat() + " 收盘",
        "index": {"name": "深证成指", "close": ix[1], "chg": ix[2]},
        "rules": {"volMult": VOL_MULT, "rsGap": RS_GAP, "trigger": TRIGGER},
        "themes": themes,
    }


if __name__ == "__main__":
    snap = build()
    json.dump(snap, open("snapshot.json", "w"), ensure_ascii=False, indent=1)
    json.dump({"themes": THEMES, "rules": snap["rules"]},
              open("config.json", "w"), ensure_ascii=False, indent=1)
    print(f"{snap['date']}  深证成指 {snap['index']['close']} ({snap['index']['chg']:+.1f}%)\n")
    for t in snap["themes"]:
        mark = "★ 共振" if t["fired"] else "      "
        tl = " ".join(str(x["n"]) for x in t["timeline"])
        print(f"{mark} {t['name']:<18} {t['hits']}/{t['total']}  均分{t['avgScore']:.2f}  "
              f"板块{t['basketChg']:+.1f}%   近8日共振数 [{tl}]")
        for s in t["stocks"]:
            print(f"        {s['name']:<6} {s['px']:>8.2f} {s['chg']:+6.1f}%  量{s['vol']:.2f}x  "
                  f"{'站上' if s['ma'] else '    '}  超额{s['rs']:+6.1f}  → {s['score']}分")
